 const n=D0.length,W=1330,Hh=290,x0=6,gw=(W-x0)/n,bw=Math.min(28,gw/3.5),mx=Math.max(1,...D0.map(d=>Math.max(d.pv,d.cons,d.imp)))*1.15;
 let s=`<svg width="${W}" height="${Hh+70}" viewBox="0 0 ${W} ${Hh+70}">`;
 [0,.5,1].forEach(f=>{const y=Hh-f*Hh*.88;s+=`<line x1="0" x2="${W}" y1="${y}" y2="${y}" stroke="#16314f"/><text x="2" y="${y-5}" fill="#6fb8ff" font-size="17" font-family="Courier New">${fr(mx*f/1.15,0)} kWh</text>`});
 D0.forEach((d,i)=>{const cx=x0+i*gw+gw/2,hp=d.pv/mx*Hh*.88,hc=d.cons/mx*Hh*.88,hi=d.imp/mx*Hh*.88,x1=cx-bw*1.5-4,x2=cx-bw*.5,x3=cx+bw*.5+4,ime=(d.ime!==undefined?d.ime:d.imp*TARIF_HP);
  s+=`<rect x="${x1}" y="${Hh-hp}" width="${bw}" height="${hp}" rx="3" fill="#2dff8a"/><rect x="${x2}" y="${Hh-hc}" width="${bw}" height="${hc}" rx="3" fill="#35d0ff"/><rect x="${x3}" y="${Hh-hi}" width="${bw}" height="${hi}" rx="3" fill="#ff9a4a"/>`;
  if(n<=7)s+=`<text x="${x1+bw/2}" y="${Hh-hp-6}" fill="#2dff8a" font-size="19" font-weight="700" text-anchor="middle" font-family="Courier New">${fr(d.pv,0)}</text><text x="${x2+bw/2}" y="${Hh-hc-6}" fill="#35d0ff" font-size="19" font-weight="700" text-anchor="middle" font-family="Courier New">${fr(d.cons,0)}</text><text x="${x3+bw/2}" y="${Hh-hi-6}" fill="#ffb070" font-size="19" font-weight="700" text-anchor="middle" font-family="Courier New">${fr(d.imp,1)}</text>`;
  const lab=n<=7?d.d.toLocaleDateString('fr-FR',{weekday:'short',day:'numeric'}).toUpperCase().replace('.',''):(i%3===0?d.d.getDate()+'/'+(d.d.getMonth()+1):'');
  s+=`<text x="${cx}" y="${Hh+28}" fill="#9fc8ff" font-size="${n<=7?21:17}" text-anchor="middle" font-family="Courier New" font-weight="700">${lab}</text>`;
  if(n<=7)s+=`<text x="${cx}" y="${Hh+54}" fill="#ffb070" font-size="18" text-anchor="middle" font-family="Courier New" font-weight="700">${fr(d.imp,1)} kWh · ${fr(ime,2)} €</text>`});
 s+='</svg>';
 const T=k=>sum(D0.map(d=>d[k])),pv=T('pv'),cons=T('cons'),imp=T('imp'),exp=T('exp'),eur=T('eur'),self=T('self'),ime=sum(D0.map(d=>d.ime!==undefined?d.ime:d.imp*TARIF_HP));
 const card=(l,v,u,c)=>`<div class="hcd"><div class="sl">${l}</div><div class="sv gl" style="color:${c}">${v}<span style="font-size:26px"> ${u}</span></div></div>`;
