const BS={min:MIN_PCT,max:MAX_PCT,touched:false,det:null,t:0};
function detectBatSet(){const h=getHass(),res=[];
 UN.forEach((u,i)=>{const o={u,i,min:null,max:null,cand:[]};
  const man=BATSET[u.id]||{};
  if(!h){o.min={id:'number.sim_'+u.id+'_min_soc',v:MIN_PCT,lo:0,hi:50,st:5};o.max={id:'number.sim_'+u.id+'_soc_set',v:MAX_PCT,lo:40,hi:100,st:5};res.push(o);return}
  const pre=(u.lvl||'').replace(/^sensor\./,'').replace(/_(electric_level|pile_average|soc_level|battery_level|state_of_charge|soc)$/,'');
  const mk=(id)=>{const s=h.states[id];if(!s)return null;const a=s.attributes||{};return{id,v:+s.state,lo:a.min!==undefined?+a.min:0,hi:a.max!==undefined?+a.max:100,st:a.step!==undefined?+a.step:1}};
  if(man.min)o.min=mk(man.min);if(man.max)o.max=mk(man.max);
  if(!o.min||!o.max)Object.keys(h.states).forEach(id=>{if(!id.startsWith('number.')||!(id.includes(pre)||/(^|[._])cluster_/.test(id)))return;const a=h.states[id].attributes||{},un=a.unit_of_measurement;if(un&&/^(w|kw|a|v|wh|kwh|°c|c)$/i.test(un))return;const k=id.replace('number.','');o.cand.push(id);
   if(!o.min&&/min.?soc|soc.?min|minsoc|discharge.?limit|limite.?decharge|reserve|minimum|soc.?security/.test(k))o.min=mk(id);
   else if(!o.max&&!/discharge|decharge|min/.test(k)&&/soc.?set|socset|max.?soc|soc.?max|charge.?limit|limite.?charge|upper/.test(k))o.max=mk(id)});
  res.push(o)});
 return res}
function batSetInfo(){if(!BS.det||Date.now()-BS.t>10000){BS.det=detectBatSet();BS.t=Date.now()}return BS.det}
function syncLimits(){const L=batSetInfo(),mins=L.map(o=>o.min&&o.min.v).filter(v=>v!==null&&v!==undefined&&!isNaN(v)),maxs=L.map(o=>o.max&&o.max.v).filter(v=>v!==null&&v!==undefined&&!isNaN(v));
 if(mins.length){MIN_PCT=Math.max(...mins)}if(maxs.length){MAX_PCT=Math.min(...maxs)}
 if(!BS.touched){BS.min=MIN_PCT;BS.max=MAX_PCT}}
function batSetHTML(){const L=batSetInfo(),ok=L.filter(o=>o.min&&o.max).length,ref=L.find(o=>o.min)||{min:{lo:0,hi:50,st:5}},rmx=L.find(o=>o.max)||{max:{lo:40,hi:100,st:5}};
 const lo1=ref.min.lo,hi1=Math.min(ref.min.hi,60),lo2=Math.max(rmx.max.lo,20),hi2=rmx.max.hi,s1=Math.max(1,ref.min.st||1),s2=Math.max(1,rmx.max.st||1);
 let h=`<div class="mi full"><div style="font-size:22px;color:#9fc0ee;letter-spacing:2px;margin-bottom:6px">RÉGLAGE GLOBAL · ${L.length} BATTERIES</div>
 <div class="bsl"><span class="bsn" style="color:#ffb13b" id="bsMin">${BS.min}%</span><span class="bsk">MINI<small>la batterie s'arrête de se vider</small></span><input type="range" data-b="min" min="${lo1}" max="${hi1}" step="${s1}" value="${BS.min}"></div>
 <div class="bsl"><span class="bsn" style="color:#2dff8a" id="bsMax">${BS.max}%</span><span class="bsk">MAXI<small>la batterie s'arrête de se charger</small></span><input type="range" data-b="max" min="${lo2}" max="${hi2}" step="${s2}" value="${BS.max}"></div>
 <div class="mc" style="margin-top:8px"><div class="bt w" data-b="apply" style="height:70px;font-size:26px;border-color:#2dff8a;color:#2dff8a">✔ APPLIQUER AUX ${ok} BATTERIES</div></div>
 ${ok<L.length?'<div style="color:#ffb13b;font-size:19px;margin-top:8px">⚠ '+(L.length-ok)+' batterie(s) sans réglage trouvé (voir ci-dessous)</div>':''}</div>`;
 h+=L.map(o=>`<div class="mi"><div class="mh"><b>${o.u.name}</b><span class="st ${o.min&&o.max?'ok':''}">${o.min&&o.max?'min '+(isNaN(o.min.v)?'?':o.min.v)+'% · max '+(isNaN(o.max.v)?'?':o.max.v)+'%':'NON TROUVÉ'}</span></div>
  <div style="font-size:14px;color:#6f86a8;word-break:break-all;margin-top:4px">${o.min?o.min.id:'min : ?'}<br>${o.max?o.max.id:'max : ?'}${(!o.min||!o.max)&&o.cand.length?'<br>trouvés : '+o.cand.slice(0,6).join(', '):''}</div></div>`).join('');
 return h}
function applyBatSet(){const L=batSetInfo();let n=0;L.forEach(o=>{if(o.min){svc('number','set_value',{entity_id:o.min.id,value:Math.max(o.min.lo,Math.min(o.min.hi,BS.min))});o.min.v=BS.min;n++}if(o.max){svc('number','set_value',{entity_id:o.max.id,value:Math.max(o.max.lo,Math.min(o.max.hi,BS.max))});o.max.v=BS.max;n++}});
 MIN_PCT=BS.min;MAX_PCT=BS.max;BS.touched=false;BS.t=0;toast('✔ Mini '+BS.min+'% · Maxi '+BS.max+'% envoyés ('+n+' réglages)')}
