function drawChart(data){const box=$('#pch'),W=680,H=170,pl=8,pr=8,pt=10,pb=22,now=Date.now(),t0=now-24*3600e3;
 const sp=data.some(d=>d.sr.fc)?36:24,X=t=>pl+(clamp(t,t0,t0+sp*3600e3)-t0)/(sp*3600e3)*(W-pl-pr);let g='';
 for(let k=0;k<=6;k++){const t=t0+k*sp/6*3600e3,x=X(t);g+=`<line x1="${x}" y1="${pt}" x2="${x}" y2="${H-pb}" stroke="#1d3354"/><text x="${x}" y="${H-6}" fill="#5d7aa6" font-size="11" text-anchor="middle">${String(new Date(t).getHours()).padStart(2,'0')}h</text>`}
 g+=`<line x1="${X(now)}" y1="${pt}" x2="${X(now)}" y2="${H-pb}" stroke="#fff" stroke-dasharray="3 3" opacity=".6"/>`;let lg='';
 data.forEach(({sr,pts})=>{if(!pts.length){lg+=`<span style="color:${sr.color}">${sr.label} : aucune donnée</span>`;return}
  const vs=pts.map(p=>p[1]);let lo=Math.min(...vs),hi=Math.max(...vs);if(hi-lo<1e-6)hi=lo+1;if(sr.u==='%'){lo=Math.min(lo,0);hi=Math.max(hi,100)}else lo=Math.min(lo,0);
  const Y=v=>pt+(1-(v-lo)/(hi-lo))*(H-pt-pb),line=pts.map(p=>X(p[0]).toFixed(1)+','+Y(p[1]).toFixed(1)).join(' ');
  g+=`<polygon points="${X(pts[0][0])},${Y(lo)} ${line} ${X(pts[pts.length-1][0])},${Y(lo)}" fill="${sr.color}" opacity=".13"/><polyline points="${line}" fill="none" stroke="${sr.color}" stroke-width="2" stroke-linejoin="round"/>`;
  const f=v=>sr.u==='%'?Math.round(v)+' %':sr.u==='W'?(Math.abs(v)>=1000?fr(v/1000,2)+' kW':Math.round(v)+' W'):fr(v,1)+' '+sr.u;
  lg+=`<span style="color:${sr.color}">■ ${sr.label} · maxi ${f(hi)} · mini ${f(Math.min(...vs))}</span>`});
 box.innerHTML=`<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${g}</svg><div class="lg">${lg}</div>`}
